-- FOON 99-feature catalog for restaurants, cafes and stores.
-- Additive and idempotent: no existing rows or business data are deleted.

SELECT p.id,f.id,CASE
 WHEN p.id='starter' AND f.id IN ('welcome_page','custom_domain','seo_metadata','social_links','restaurant_settings','multilingual_ui','rtl_support','dark_mode','pwa_install','branded_qr','menu','restaurant_packages','specialities','product_images','allergens_labels') THEN 1
 WHEN p.id='basic' AND f.id IN ('welcome_page','custom_domain','seo_metadata','social_links','restaurant_settings','multilingual_ui','rtl_support','dark_mode','pwa_install','branded_qr','menu','restaurant_packages','specialities','product_images','allergens_labels','nutrition_info','stock_visibility','scheduled_availability','bulk_import','barcode_catalog','recipe_costing','product_reviews','orders','dine_in','pickup','room_service','whatsapp_order','order_status_tracking','scheduled_orders','multi_branch_orders','order_notes','split_orders','refunds_returns','guest_checkout','pos','offline_pos','cash_payment','online_payment','payment_links','digital_receipts') THEN 1
 WHEN p.id='business' AND f.id IN ('welcome_page','custom_domain','seo_metadata','social_links','restaurant_settings','multilingual_ui','rtl_support','dark_mode','pwa_install','branded_qr','menu','restaurant_packages','specialities','product_images','allergens_labels','nutrition_info','stock_visibility','scheduled_availability','bulk_import','barcode_catalog','recipe_costing','product_reviews','orders','dine_in','pickup','room_service','whatsapp_order','order_status_tracking','scheduled_orders','multi_branch_orders','order_notes','split_orders','refunds_returns','guest_checkout','pos','offline_pos','cash_payment','online_payment','payment_links','digital_receipts','split_payments','tips_service_charge','tax_invoicing','cash_drawer','reservations','tables','qr_menu','waitlist','table_status','floor_sections','table_service_events','waiter_call','reservation_reminders','deposits_no_show','inventory','low_stock_alerts','ingredient_units','stock_movements','purchase_orders','suppliers','receiving','waste_tracking','inventory_counts','menu_stock_deduction','staff','roles_permissions','branch_access','shifts_attendance','kds','kitchen_routing') THEN 1
 WHEN p.id='professional' THEN 1 ELSE 0 END,NULL,UNIX_TIMESTAMP()*1000
FROM package_plans p CROSS JOIN feature_definitions f
WHERE f.id IN ('welcome_page','custom_domain','seo_metadata','social_links','restaurant_settings','multilingual_ui','rtl_support','dark_mode','pwa_install','branded_qr','menu','restaurant_packages','specialities','product_images','allergens_labels','nutrition_info','stock_visibility','scheduled_availability','bulk_import','barcode_catalog','recipe_costing','product_reviews','orders','dine_in','pickup','room_service','whatsapp_order','order_status_tracking','scheduled_orders','multi_branch_orders','order_notes','split_orders','refunds_returns','guest_checkout','pos','offline_pos','cash_payment','online_payment','payment_links','digital_receipts','split_payments','tips_service_charge','tax_invoicing','cash_drawer','reservations','tables','qr_menu','waitlist','table_status','floor_sections','table_service_events','waiter_call','reservation_reminders','deposits_no_show','inventory','low_stock_alerts','ingredient_units','stock_movements','purchase_orders','suppliers','receiving','waste_tracking','inventory_counts','menu_stock_deduction','staff','roles_permissions','branch_access','shifts_attendance','kds','kitchen_routing','printing','delivery_staff','contacts','customer_segments','loyalty_points','coupons_discounts','campaigns','abandoned_cart','feedback_reviews','affiliate','analytics','product_analytics','staff_performance','inventory_reports','financial_reports','export_reports','custom_reports','webhooks_api','email_notifications','pwa_push','sms_notifications','accounting_integration','delivery_integrations','audit_log','backups_restore','rate_limiting','multi_tenant_isolation','api_keys','priority_support');

